  run: 5.2,
  walk: 3.05,
  crouch: 2.35,
  groundAccel: 46,
  airAccel: 7,
  friction: 9.5,
  gravity: 21,
  jump: 6.3,
  eyeStand: 1.6,
  eyeCrouch: 1.02,
};

