    return;
  }
  if (bot.state !== 'engage' && bot.state !== 'investigate' && bot.state !== 'reload') {
    const hold = bot.holdNode >= 0 ? bot.holdNode : siteHoldNode(bot.site);
    if (hold >= 0 && bot.goalNode !== hold) {
